public class Color {
  public readonly byte Red;
  public readonly byte Green;
  public readonly byte Blue;

  public Color(byte r, byte g, byte b) { Red = r; Green = g; Blue = b; }

  public Color MixWith(Color other) {
    return new Color(   // 別のインスタンスを作る
      (byte) Math.Min(this.Red + other.Red, 255),
      (byte) Math.Min(this.Green + other.Green, 255),
      (byte) Math.Min(this.Blue + other.Blue, 255));
  }

  public override bool Equals(object obj) {
    var other = obj as Color;
    return other != null && Red == other.Red
        && Green == other.Green && Blue == other.Blue;
  }
  public static bool operator ==(Color lhs, Color rhs) {
    if (Object.ReferenceEquals(lhs, null)) return Object.ReferenceEquals(rhs, null);
    return lhs.Equals(rhs);
  }
  public static bool operator !=(Color lhs, Color rhs) => !(lhs == rhs);
  public override int GetHashCode() => ToString().GetHashCode();
}

